/** REG-MOVCONTABLES: salida canónica del motor GL, una partida por registro. */
@Entity
@Table(name = "MOV_CONTABLE")
public class MovimientoContable {

    @Id @GeneratedValue private Long id;

    @Column(length = 5)  private String filial;           // X(05)
    private int producto;                                  // 9(04) COMP
    private int instrumento;                               // 9(02) COMP
    private int sucPromotora;                              // 9(04) COMP
    private int moneda;                                    // 9(04) COMP
    @Column(length = 12) private String cuentaContable;   // 9(12): 12 dígitos con ceros a la izquierda

    @Column(precision = 16, scale = 2)
    private BigDecimal importe;                            // 9(14)V99 COMP, sin signo

    private int tipoMov;                                   // 9
    @Enumerated(EnumType.ORDINAL)
    private Naturaleza naturaleza;                         // 9: 1 = cargo, 2 = abono
    private long folio;
    private int sector, actividad, banca, causa, origen;
    private long autS151;
    private int cveTran, banco;

    /** RMC-CTA1-CONT (REDEFINES): primer dígito de la cuenta. */
    public int grupoCuenta() { return cuentaContable.charAt(0) - '0'; }

    /** RMC-CTA4-CONT (REDEFINES): cuenta de mayor de 4 dígitos. */
    public String mayor()    { return cuentaContable.substring(0, 4); }

    public void setImporte(BigDecimal v) {
        if (v.signum() < 0 || v.setScale(0, RoundingMode.DOWN).precision() > 14)
            throw new ImporteFueraDeRangoException(v);     // 9(14)V99 sin signo
        this.importe = v.setScale(2, RoundingMode.UNNECESSARY);
    }
}

@Service
@RequiredArgsConstructor
public class MotorAsientosGl {

    private final P109Properties props;
    private final ProcesoMovimientos movimientos;   // 20000 / 20001
    private final Bitacora bitacora;                // 30000 / 30001
    private final CuadreContable cuadre;            // 40000
    private final PosicionContableService posicion; // 50000
    private final ReporteHacienda hacienda;         // 70000
    private final ReporteRechazos rechazos;         // 60000

    /** 000000-PROGRAMA: ruteo por W77-SISTEMA-PARAMETRO (PROCEDURE DIVISION USING). */
    public void ejecuta(int sistema, ContextoProceso ctx) {
        if (sistema == 500) {                       // caja: ruta propia y STOP RUN
            movimientos.procesaCaja(ctx);
            bitacora.generaCaja(ctx);
            return;
        }
        movimientos.procesa(ctx);
        bitacora.genera(ctx, sistema == 264 ? Datalake.abre(ctx) : Datalake.NINGUNO);

        boolean conCuadre = ctx.nombreBaseSaldos().isPresent() || sistema == 502 || sistema == 702;
        if (conCuadre) {
            cuadre.genera(ctx);
            if (sistema != 502 && sistema != 702 && Set.of(1, 2, 5, 6).contains(ctx.tipoBd())) {
                posicion.actualiza(ctx);
            }
        }
        if (sistema == 701) {
            hacienda.genera(ctx);
        }
        // Línea 7848: "NOT = 702 OR 502" en COBOL-85 se expande a (NOT = 702) OR (NOT = 502),
        // que siempre es verdadero. Se replica tal cual hasta que el SME confirme la intención.
        if (props.rechazos().replicarCondicionLegada() || (sistema != 702 && sistema != 502)) {
            rechazos.genera(ctx);
        }
    }
}

/** Puerto hacia el calendario bancario que reemplaza a THECALENDAR IN LOCSUP. */
