    /** Función 13: n días hábiles hacia adelante (excluye sábados, domingos y festivos Banxico). */
    Optional<LocalDate> diasHabilesAdelante(LocalDate desde, int dias);
    /** Función 15: n días hábiles hacia atrás (usada en 50000-POSICION). */
    Optional<LocalDate> diasHabilesAtras(LocalDate desde, int dias);
}

// 10000-INICIO-PROGRAMA
// Formato 13 (Cronos 2000) = AAAAMMDD; el formato 3 previo de 6 dígitos quedó comentado.
LocalDate fechaFutura = calendario.diasHabilesAdelante(ctx.fechaProceso(), 1)
        .orElseThrow(() -> {
            alertas.operador(TipoMensaje.E, 10105, "ERROR AL CALCULAR FECHA DE DIA SIGUIENTE ");
            return new ProcesoAbortadoException("THECALENDAR función 13");   // SET MYSELF(STATUS) TO -1
        });
ctx.setFechaFutura(fechaFutura);                                              // WKS-FECHA-FUT

// 20000-PROCESA-MOVIMIENTOS: lectura y validación del header de LOG151
Log151Header hdr = log151.leeHeader();                     // READ LOG151 INTO A00-R00-HDR-MOV

Optional<String> error =
      !"HD".equals(hdr.tipo())                       ? Optional.of("ERROR EN HEADER ARCHIVO : " + hdr.tipo())
    : !hdr.fecha().equals(ctx.fechaProceso())        ? Optional.of("ERROR EN FECHAS,ARCHIVO : " + hdr.fecha()
                                                           + " DIFERENTE A FECHA DE PROCESO : " + ctx.fechaProceso())
    : Optional.empty();

error.ifPresent(msg -> {
    alertas.operador(TipoMensaje.O, msg);                  // 000-030-IMPRIME-MENSAJE
    // En P109 el abort está comentado (SET MYSELF(STATUS) TO -1): el proceso continúa.
    if (props.log151().abortarSiHeaderInvalido()) {        // default false = comportamiento actual
        throw new HeaderLog151InvalidoException(msg);
    }
});

/** LOG151: el fin lógico es el registro FUNCION = 99, no el fin físico del archivo. */
public class Log151ItemReader implements ItemReader<RegistroLog151> {
    private final ItemReader<RegistroLog151> delegado;
    private boolean fin;

    @Override
    public RegistroLog151 read() throws Exception {
        if (fin) return null;
        RegistroLog151 r = delegado.read();               // READ LOG151 ... AT END
        if (r == null || r.funcion() == 99) {             // centinela: nunca se procesa como asiento
            fin = true;
            return null;
        }
        return r;
    }
}

// 21000-ESCOGE-MOVS, tramo de selección (ItemProcessor)
@Override
public RegistroLog151 process(RegistroLog151 r) {
    if (r.funcion() == 1 && (r.status() == 1 || r.status() == 2)) {
        contadores.procesados++;                          // W77-TP-REG-PROCESADOS
        grabaArchivos.graba(r);                           // 21100-GRABA-ARCHIVOS
        return r;
    }
    contadores.eliminados++;                              // W77-TP-REG-ELIMINADOS
    return null;
}

// 21100-GRABA-ARCHIVOS, tramo final (dentro de IF A00-R01-ORIGEN = 1 OR = 2 abierto en L10585)
@Transactional
public void graba(RegistroLog151 r) {
    int sistema = ctx.sistema();
    if (r.origen() == 1 || r.origen() == 2) {
        bitacora.graba(r);                                     // 21110-GRABA-MOV-BITACORA
        if (r.status() == 1) punteo.graba(r);                  // retroalimentación al origen
    }
    if (r.status() == 1 && r.origen() == 3 && sistema == 264) {
        punteo.graba(r);
    }
    if (r.status() == 1 && (r.origen() == 1 || r.origen() == 3)) {   // STATUS 2 nunca genera asiento
        MovimientoSort base = MovimientoSort.builder()
                .producto(r.producto()).instrumento(r.instrumento())
                .sector(r.sector()).actividad(0).banca(r.banca())
                .sucProm(r.sucProm()).moneda(r.moneda()).origen(r.origen())
                .indConta(r.indConta())
                .banco(bancoPorSistema(r, sistema))               // 21115-VERIFICA-SISTEMA
                .fecVen(sistema == 87 ? r.fecVen087() : 0)
                .build();
        movContaSort.addAll(desglosaCveTran(r, base));           // 21116-GRABA-MOVSORT-CONTA
    }
}

/** 21115-VERIFICA-SISTEMA: de qué campo de LOG151 sale el banco del asiento. */
static int bancoPorSistema(RegistroLog151 r, int sistema) {
    int banco = 0;                                               // MOVE ZEROS TO RMS-BANCO
    if (sistema == 18 || sistema == 17) {
        banco = r.bancoS018() > 0 ? r.bancoS018() : 0;
    }
    if (sistema == 703 && !r.bancosTexto().isBlank()) {
        banco = r.bancos();
    }
    if (sistema == 264) {                                        // SPEI
        if (r.moneda() == 1) banco = 0;                          // pesos: sin dimensión banco
        else if (!r.bancosTexto().isBlank()) banco = r.bancos();
    }
    return banco;
}

/** 21116-GRABA-MOVSORT-CONTA: un registro de MOVCONTASORT por cada CVETRAN mayor que cero. */
static List<MovimientoSort> desglosaCveTran(RegistroLog151 r, MovimientoSort base) {
    return IntStream.rangeClosed(1, 5)
            .filter(i -> r.cveTran(i) > 0)
            .mapToObj(i -> base.conPartida(r.cveTran(i), r.esqCon(i), cabeEn14Enteros(r.importe(i))))
            .toList();
}

/** MOVE de 9(16)V99 a 9(14)V99: COBOL descarta los dos dígitos altos sin aviso. */
static BigDecimal cabeEn14Enteros(BigDecimal v) {
    if (v.compareTo(new BigDecimal("99999999999999.99")) > 0) throw new ImporteFueraDeRangoException(v);
    return v;
}

/** Clave de corte de MOVCONTASORT: las 11 dimensiones del SORT SMOVCONTASORT. */
public record ClaveAsiento(String filial, int origen, int moneda, int banco, int sucProm,
                           int fecVen, int producto, int instrumento, int sector,
                           int cveTran, int esqCon) {
    static ClaveAsiento de(MovimientoSort m) {
        return new ClaveAsiento(m.filial(), m.origen(), m.moneda(), m.banco(), m.sucProm(),
                m.fecVen(), m.producto(), m.instrumento(), m.sector(), m.cveTran(), m.esqCon());
    }
}

/** 20001-PROCESA-MOVCONTA + 20010-ACUMULA-IMPORTE sobre un flujo ya ordenado por la clave. */
public void acumula(PeekingIterator<MovimientoSort> ordenados, Consumer<AsientoAcumulado> grabaMovCont) {
    while (ordenados.hasNext()) {
        MovimientoSort primero = ordenados.next();
        ClaveAsiento clave = ClaveAsiento.de(primero);
        BigDecimal suma = primero.importe();                     // W77-IMP-SORT 9(16)V99
        while (ordenados.hasNext() && ClaveAsiento.de(ordenados.peek()).equals(clave)) {
            suma = suma.add(ordenados.next().importe());         // ADD exacto, escala 2
        }
        // ACTIVIDAD, BANCA e IND-CONTA están fuera de la clave: se heredan del primer registro.
        grabaMovCont.accept(new AsientoAcumulado(clave, suma,
                primero.actividad(), primero.banca(), primero.indConta()));   // 21118-GRABA-MOVCONT
    }
}
