/** 21120-GRABA-MOV-CONTABLE: CVETRAN -> agrupación contable -> esquema -> partidas. */
void grabaMovContable(AsientoAcumulado a) {
    int cve = a.clave().cveTran();
    if (cve <= 0 || catalogos.inds250(cve) != 2) {
        return;                                                   // no contabilizable, sin traza
    }
    if (catalogos.formatoCatalogoTransacciones() == 2) {          // WKS-TIPO-CAT = 2 (12020-CAT-TRANS)
        esquemaPorCatalogo.resuelve(a);                           // 21121-LEE-ESQUEMA1 (ARCH-CAT)
        return;
    }
    int agrupacion = catalogos.agrupacionContable(cve);           // WKS-PT-AGR-CONT -> W77-IND
    int esqCon = a.clave().esqCon();                              // W77-IND2
    // La validación de rango (IND 1..200, IND2 1..150) está comentada en el fuente.
    Optional<Integer> esquema = cat7.findEsquema(agrupacion, esqCon);   // 21122-MUEVE-ESQUEMA
    if (esquema.isEmpty()) {                                      // W77-IND3 = 0
        errores.graba(ErrorAsiento.de(a, "ESQUEMA NO EXISTE"));   // 21105-IMPRIME-ERRORES
        return;
    }
    for (int partida = 1; partida <= 10; partida++) {             // VARYING W77-IND4 FROM 1 BY 1
        if (!mueveCuentasContables(a, esquema.get(), partida)) break;   // fin de partidas del esquema
    }
}

/** 21121-MUEVE-CUENTAS-CONTABLES: una partida del esquema a MOVCONTABLES. */
boolean mueveCuentasContables(AsientoAcumulado a, int esquema, int partida) {
    MovimientoContable mc = a.nuevoMovimiento();
    if (ctx.sistema() == 87) mc.setProducto(87);                  // cheques: producto fijo 087

    // Partida 1: READ ARCH-ESQCON KEY IS KEY-ESQ. Siguientes: READ NEXT mientras sea el mismo esquema.
    Optional<EsquemaContable> eq = esqcon.find(esquema, partida);
    if (eq.isEmpty()) {
        if (partida == 1) {
            alertas.operador(TipoMensaje.E, 20202, "ERROR READ, ARCHIVO ESQCON");
        }
        return false;   // en el fuente el INVALID KEY no corta el ciclo; ver riesgo
    }
    EsquemaContable e = eq.get();
    if (e.naturaleza() != 1 && e.naturaleza() != 2) {
        return true;                                              // descarte silencioso, sin traza
    }
    mc.setTipoMov(e.tipoMov());
    mc.setNaturaleza(Naturaleza.of(e.naturaleza()));
    mc.setCausa(e.causa());
    mc.setCuentaContable(e.cuenta());

    if (mc.grupoCuenta() == 0) {                                  // cuenta sin grupo: se manda a control
        mc.setCuentaContable("5" + mc.getCuentaContable().substring(1));
        mc.setBanca(0); mc.setSector(0); mc.setActividad(0);      // pierde la sectorización
    } else if (ctx.sistema() == 408 && a.sector() == 0) {         // fallback C408
        mc.setActividad(0); mc.setBanca(0);
        mc.setSector(switch (a.clave().instrumento()) { case 10 -> 31; case 20 -> 32; default -> 0; });
    } else {
        mc.setSector(a.sector()); mc.setActividad(a.actividad()); mc.setBanca(a.banca());
    }
    mc.setFolio(ctx.folio());
    movContables.save(mc);                                        // WRITE REG-MOVCONTABLES
    return true;
}

// 40000-GENERA-CUADRE-CONTABLE: cierre del paquete de una cuenta
String cuenta = paquete.cuentaAnterior();                         // WS-CTA-250-ANT (12 dígitos)
if (ctx.sistemaCentralContable()) {                               // W88-SIST-CEN-CONTABLE
    if (cuenta.charAt(0) != '5') validaCuenta1503(paquete);       // 40005-VALIDA-CTA-1503
} else if (cuenta.equals(props.cuadre().cuentaCentral())) {       // 150399000000
