public interface PosicionRepository extends JpaRepository<PosicionContable, PosicionId> {
    @Lock(LockModeType.PESSIMISTIC_WRITE)                         // LOCK B72SXPOSCONTA
    @Query("select p from PosicionContable p where p.id = :id")
    Optional<PosicionContable> findForUpdate(PosicionId id);
}

/** 54000-ACTUALIZA-POSICION: upsert de S151B72POSCONTA con los totales del día. */
@Transactional
public void actualizaPosicion(LlaveCuadre k, BigDecimal cargos, BigDecimal abonos) {
    var id = new PosicionId(ctx.csiProceso(), ctx.fechaProceso(), k.banco(),
                            0,                                    // FID siempre 0 en la llave
                            k.producto(), k.instrumento(), k.moneda(), k.cuenta(), k.causa(), k.sector());

    PosicionContable p = repo.findForUpdate(id)
            .orElseGet(() -> PosicionContable.nueva(id, BigDecimal.ZERO.setScale(2)));   // CREATE, SDOANT = 0

    p.setCargos(cargos);                                          // MOVE: reemplaza, no acumula
    p.setAbonos(abonos);
    p.setSaldoActual(p.getSaldoAnterior().subtract(cargos).add(abonos));   // sin ROUNDED: escala 2 exacta
    repo.save(p);                                                 // STORE S151B72POSCONTA
}
